import { useState, useMemo, type FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [success, setSuccess] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_PATTERN.test(email), [email]);
  const showError = emailTouched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid && email.length > 0;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSuccess(true);
  };

  return (
    <div style={{ maxWidth: 420, display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}>
      {success && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-2, 8px)' }}>
            <span>{email} получит приглашение в команду.</span>
            <JxButton
              variant="ghost"
              size="sm"
              iconOnly
              aria-label="Закрыть сообщение"
              onClick={() => setSuccess(false)}
            >
              ×
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => {
            setEmail(event.target.value);
            setSuccess(false);
          }}
          onBlur={() => setEmailTouched(true)}
          helperText={showError ? undefined : 'Приглашение придёт на этот адрес'}
          errorText={showError ? 'Введите адрес в формате name@example.com' : undefined}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

